import React, { createContext, useEffect, useState } from "react";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import { useTranslation } from "react-i18next";
import Dropdown from "react-bootstrap/Dropdown";
import jsondata from "../components/json/level1_new.json";
import nextbtn from "../Img/next.png";
import previousbtn from "../Img/previous.png";
import "../../src/styles/styles.css";
// import {
//   Dialog,
//   DialogTitle,
//   DialogContent,
//   DialogActions,
// } from "@material-ui/core";
import DialogContentText from "@mui/material/DialogContentText";
import arrayShuffle from "array-shuffle";
import { Instruction_6, Instruction_7 } from "./Instruction.js";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import useWebSocket from "react-use-websocket";
import ReactGA from "react-ga4";
import { useNavigate } from "react-router-dom";
import "@fontsource/poppins/500.css";

import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Slide,
  Tooltip,
} from "@mui/material";

import IconButton from "@mui/material/IconButton";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import Box from "@mui/material/Box";

export const CountContext = createContext(null);

function LevelfirstMidContent({ changeInst }) {
  const { t, i18n } = useTranslation();
  let [MainArr, setMainArr] = useState([]);
  let [currentIndex, setCurrentIndex] = useState(0);
  let [currentWord, setCurrentWord] = useState("");
  let [currentFeedback, setCurrentFeedback] = useState("");
  let [currentletterArr, setCurrentletterArr] = useState([]);
  let [correctletterArr, setCorrectletterArr] = useState([]);
  var [changecolor, setChangecolor] = useState([]);
  var [open1, setOpen1] = useState(false);
  let [vallength, setVallength] = useState([]);
  let [flag, setFlag] = useState(false);
  let [flag1, setFlag1] = useState(false);
  let [flag2, setFlag2] = useState(true);

  var [count2, setCount2] = useState(0);

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 1 page");

  const navigate = useNavigate();

  let details = navigator.userAgent;
  let regexp = /android|iphone|kindle|ipad/i;
  let isMobileDevice = regexp.test(details);

  useEffect(() => {
    console.log("main-array is here " + MainArr.length);

    jsondata.map((jsondataitem, index1) => {
      console.log("shuffled data", arrayShuffle(jsondataitem.words));
      addtoMainArr(arrayShuffle(jsondataitem.words));
    });
  }, [jsondata]);

  const addtoMainArr = (arraydata) => {
    console.log("addtoMainArr call ");
    setMainArr((prev) => [...prev, ...arraydata]);
    console.log("MainArr shuffled data ===>", MainArr);
  };

  useEffect(() => {
    var changecolorTemp = [];

    MainArr.map((MainAritem, index1) => {
      if (currentIndex == index1) {
        setCurrentWord(MainAritem.line);
        setCurrentFeedback(MainAritem.feedback);
        MainAritem.letter.map((letteritem, index2) => {
          console.log("letteritem is", letteritem);
          setCurrentletterArr((prev) => [...prev, letteritem]);
        });

        MainAritem.correct_letter.map((correctletteritem, index3) => {
          setCorrectletterArr((prev) => [...prev, correctletteritem]);
          changecolorTemp.push(0);
        });
        setChangecolor(changecolorTemp);
      }
    });
  }, [MainArr]);

  useEffect(() => {
    if (flag == true) {
      if (isMobileDevice) {
        changeInst(Instruction_7(t));
      }else{
      changeInst(Instruction_6(t));
      }
    }
  });

  const onDragComplete = (result) => {
    if (!result.destination) return;

    const arr = [...currentletterArr];

    console.log("arr : ==> ", arr);

    //Changing the position of Array element
    let removedItem = arr.splice(result.source.index, 1)[0];
    arr.splice(result.destination.index, 0, removedItem);
    console.log("arr is", arr);

    //Updating the list
    currentletterArr = arr;
    setCurrentletterArr(currentletterArr);

    for (let i = 0; i < correctletterArr.length; i++) {
      document.getElementById(i).style.backgroundColor = "#4C7DBF";
      document.getElementById(i).style.color = "white";
    }
  };

  const verify = (e, i) => {
    if (flag1 == true) {
      if (changecolor[i] === 2) {
        setOpen1(true);
      }
    }
  };

  const check = () => {
    ReactGA.event({
      action:
        "Hindi वर्ण-विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on check button",
      category: "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 जाँच करें clicked",
      label: "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 जाँच करें clicked",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "जाँच करें" button',
      "Clicked",
      'level-1 "जाँच करें" button clicked for one word'
    );

    flag1 = true;
    setFlag1(flag1);
    console.log("flag1 in check", flag1);

    var changecolorTemp = changecolor;

    for (let i = 0; i < correctletterArr.length; i++) {
      const element = document.getElementById(i);

      if (currentletterArr[i] === correctletterArr[i]) {
        console.log("TO change to green ======================>");
        element.style.backgroundColor = "#098B0D"; // Green background
        element.style.color = "#ffffff"; // White font color (or any color you prefer)
        changecolorTemp[i] = 1;
      } else {
        console.log("TO change to red ======================>");
        element.style.backgroundColor = "#BF4C4C"; // Red background
        element.style.color = "#ffffff"; // Black font color (or any color you prefer)
        changecolorTemp[i] = 2;
      }
    }

    console.log(changecolorTemp);

    changecolor = changecolorTemp;
    setChangecolor(changecolor);
    return false;
  };

  const handleClose1 = () => {
    setOpen1(false);
  };

  const common = (val) => {
    console.log("in common");

    setCurrentletterArr("");
    setCorrectletterArr("");

    console.log("correctletterArr", correctletterArr);

    MainArr.map((MainAritem, index1) => {
      if (currentIndex == index1) {
        setCurrentWord(MainAritem.line);
        setCurrentFeedback(MainAritem.feedback);
        MainAritem.letter.map((letteritem, index2) => {
          setCurrentletterArr((prev) => [...prev, letteritem]);
        });
        MainAritem.correct_letter.map((correctletteritem, index3) => {
          setCorrectletterArr((prev) => [...prev, correctletteritem]);
        });
      }
    });
  };

  const previous = () => {
    ReactGA.event({
      action:
        'Hindi वर्ण-विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on "पिछला शब्द" button',
      category:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 पिछला शब्द button clicked",
      label:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 पिछला शब्द button clicked",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "पिछला शब्द" button',
      "Clicked",
      'level-1 "पिछला शब्द" button clicked to attempt previous word.'
    );

    currentIndex = currentIndex - 1;
    setCurrentIndex(currentIndex);

    common(currentIndex);

    count2 = count2 - 1;
    setCount2(count2);
    console.log("after a previous button click", count2);
    console.log(
      "after previous button click vallength length is",
      vallength.length
    );

    for (let i = 0; i < correctletterArr.length; i++) {
      document.getElementById(i).style.backgroundColor = "#4C7DBF";
      document.getElementById(i).style.color = "white";
    }
    flag1 = false;
    setFlag1(flag1);

    setOpen1(false);
  };

  const next = () => {
    ReactGA.event({
      action:
        'Hindi वर्ण-विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on "अगला शब्द" button',
      category:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 अगला शब्द button clicked",
      label:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 अगला शब्द button clicked",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "अगला शब्द" button',
      "Clicked",
      'level-1 "अगला शब्द" button clicked to attempt next word.'
    );

    currentIndex = currentIndex + 1;
    setCurrentIndex(currentIndex);

    common(currentIndex);

    count2 = count2 + 1;
    setCount2(count2);
    console.log("after a next button click count2 is", count2);

    if (currentIndex >= MainArr.length) {
      setFlag(true);
    }

    for (let i = 0; i < correctletterArr.length; i++) {
      document.getElementById(i).style.backgroundColor = "#4C7DBF";
      document.getElementById(i).style.color = "white";
    }
    flag1 = false;
    setFlag1(flag1);

    setOpen1(false);
  };

  const restart = () => {
    ReactGA.event({
      action:
        'Hindi वर्ण-विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on "पुनः आरंभ" button',
      category:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 पुनः आरंभ button clicked",
      label:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 पुनः आरंभ button clicked",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "पुनः आरंभ" button',
      "Clicked",
      'level-1 "पुनः आरंभ" button clicked to restart the level-1.'
    );
    window.location.reload(false);
  };

  const level2select = () => {
    ReactGA.event({
      action:
        'Hindi वर्ण-विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on "स्तर 2" dropdown button',
      category:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 स्तर 1 dropdown button clicked",
      label:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 स्तर 1 dropdown button clicked",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "स्तर 2" dropdown button',
      "Clicked",
      'level-1 "स्तर 2" dropdown button clicked to go to level-2.'
    );
    navigate("/level2");
  };

  const NavigationPrevButtons = ({ onPrevious }) => {
    return (
      <Tooltip title="पिछला शब्द">
        <Box textAlign="center" mt={5}>
          <Stack
            direction="row"
            spacing={{ xs: 2, sm: 3, md: 4 }} // Responsive spacing
            justifyContent="center"
            mt={2}
          >
            {/* Previous Button - Responsive Size */}
            <IconButton
              onClick={onPrevious}
              sx={{
                backgroundColor: "#FC797A",
                color: "white",
                width: { xs: "50px", sm: "60px", md: "50px" }, // Responsive width
                height: { xs: "50px", sm: "60px", md: "50px" }, // Responsive height
                "&:hover": { backgroundColor: "#FC797A" },
              }}
            >
              <ArrowBackIcon
                sx={{ fontSize: { xs: "30px", sm: "35px", md: "40px" } }}
              />{" "}
              {/* Responsive icon size */}
            </IconButton>
          </Stack>
        </Box>
      </Tooltip>
    );
  };

  const NavigationNextButtons = ({ onNext }) => {
    return (
      <Tooltip title="अगला शब्द">
        <Box textAlign="center" mt={5}>
          <Stack
            direction="row"
            spacing={{ xs: 2, sm: 3, md: 4 }} // Responsive spacing
            justifyContent="center"
            mt={2}
          >
            <IconButton
              onClick={onNext}
              sx={{
                // backgroundColor: "#eee", "&:hover": { backgroundColor: "#ddd" },
                backgroundColor: "#FC797A",
                color: "white",
                width: { xs: "50px", sm: "60px", md: "50px" },
                height: { xs: "50px", sm: "60px", md: "50px" },
                "&:hover": { backgroundColor: "#FC797A" },
              }}
            >
              <ArrowForwardIcon
                sx={{ fontSize: { xs: "30px", sm: "35px", md: "40px" } }}
              />{" "}
              {/* Responsive icon size */}
            </IconButton>
          </Stack>
        </Box>
      </Tooltip>
    );
  };

  return (
    <div
      className="scrollbar-primary"
      style={{
        height: "100%",
        fontSize: "1rem",
        background: "#FCF5F5",
        borderRadius: "14px",
        overflow: "auto",
        overflowX: "hidden",
      }}
    >
      <div className="row-md-auto d-flex">
        <div className="">
          <h6
            className=""
            style={{
              marginTop: "15%",
              color: "rgb(78, 8, 112)"
              // fontFamily:"Regular"
            }}
          >
            <strong>{t("level_1")}</strong>
          </h6>
        </div>
        <div className="col text-center">
          <h5
            style={{
              paddingTop: "10px",
              color: "#4E0870",
              // fontFamily:"Regular"
            }}
          >
            {/* <strong style={{fontFamily:"Poppins"}}>विच्छेद बनाए </strong> */}

            <p>
              <strong>विच्छेद बनाएँ</strong>
            </p>
          </h5>
        </div>
        <div className="col-md-auto">
          <Dropdown className="d-flex justify-content-end">
            <Dropdown.Toggle
              variant="success"
              id="dropdown-basic"
              style={{
                background: "#A372D1",
                // fontFamily:"Regular"
              }}
            >
              {t("level")}
            </Dropdown.Toggle>

            <Dropdown.Menu style={{ background: "#F7F1FC" }}>
              <Dropdown.Item
                href="#/action-1"
                disabled="true"
                // style={{fontFamily:"Regular" }}
              >
                {t("level_1")}
              </Dropdown.Item>
              <Dropdown.Item
                onClick={level2select}
                style={{
                  color: "#350B5B",
                  // fontFamily:"Regular"
                }}
              >
                {t("level_2")}
              </Dropdown.Item>
            </Dropdown.Menu>
          </Dropdown>
        </div>
      </div>
      {flag == true ? (
           <div
                   className="mt-3 col-auto justify-content-center"
                   style={{
                     // fontSize: "16px",
                     boxShadow: "rgba(0, 0, 0, 0.16) 0px 3px 6px",
                     borderRadius: "20px",
                     backgroundColor: "white",
                     padding: "10px 20px",
                     marginTop: "2vh",
                     // display: "flex",
                     flexWrap: "nowrap",
                     gap: "10px",
                     maxWidth: "80%",
                     marginLeft: "auto",
                     marginRight: "auto",
                   }}
                 >
                   <p className="text-center">आपने सभी वाक्य पूरे कर लिए हैं।</p>{" "}
                   <br></br>
                   <p className="text-center">
                     स्तर 1 को पुनः आरंभ करने के लिए 'पुनः आरंभ' बटन पर क्लिक करें।
                   </p>
                   <br></br>
                   <div className="row-md-auto d-flex justify-content-center align-items-center">
                     <Button
                       variant="contained"
                       style={{ backgroundColor: "#A372D1" }}
                       onClick={restart}
                     >
                       {t("restart")}
                     </Button>
                   </div>
                 </div>
      ) : (
        <div
          className=" d-flex justify-content-around"
          style={{ marginTop: "2vh" }}
        >
          <div className=" d-flex justify-content-center align-items-center img-fluid">
            {currentIndex > 0 ? (
              <NavigationPrevButtons onPrevious={previous} />
            ) : (
              ""
            )}
          </div>
          <div className="row-md-auto">
            <div className=" d-flex justify-content-center align-items-center ">
              <div
                className="varn row-md-auto text-center "
                style={{
                  borderRadius: "10px",
                  // boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
                  boxShadow: " rgba(99, 99, 99, 0.2) 0px 2px 8px 0px",
                  backgroundColor: "#FFFFFF",
                  padding: "1vh",
                  textAlign: "center",
                }}
              >
                <span
                  className=""
                  style={{
                    margin: "2vh 2vh 2vh 2vh",
                    // fontFamily:"Regular"
                  }}
                >
                  <strong>{currentWord}</strong>
                </span>
              </div>
            </div>

            <div className="">
              <DragDropContext onDragEnd={onDragComplete}>
                <Droppable droppableId="characters" direction="horizontal">
                  {(provided) => (
                    <div
                      className="col d-flex justify-content-center align-items-center characters flex-wrap"
                      style={{ marginTop: "3%" }}
                      {...provided.droppableProps}
                      ref={provided.innerRef}
                    >
                      {currentletterArr == null ? (
                        <div>hdsfvsd</div>
                      ) : (
                        currentletterArr.map((item, index) => (
                          <Draggable
                            key={index}
                            draggableId={"" + index}
                            index={index}
                          >
                            {(provided) => (
                              <div
                                className={"item-card"}
                                ref={provided.innerRef}
                                {...provided.draggableProps}
                                {...provided.dragHandleProps}
                                onClick={(event) => verify(event, index)}
                                id={index}
                              >
                                <p className="label varn" id="item">
                                  {item}
                                </p>
                              </div>
                            )}
                          </Draggable>
                        ))
                      )}
                      {provided.placeholder}
                    </div>
                  )}
                </Droppable>
              </DragDropContext>
            </div>

            <div className="d-flex justify-content-center align-items-center mt-4">
              <Button
                variant="contained"
                onClick={check}
                style={{
                  background: "#A372D1",
                  color: "white",
                  // fontFamily:"Regular"
                }}
              >
                {t("check")}
              </Button>
            </div>

            <Dialog
              open={open1}
              onClose={handleClose1}
              aria-labelledby="alert-dialog-title"
              aria-describedby="alert-dialog-description"
            >
              <DialogTitle
                style={{ backgroundColor: "#BF4C4C", color: "white" }}
                sx={
                  {
                    // fontFamily:"Regular"
                  }
                }
              >
                प्रतिपुष्टि
              </DialogTitle>
              <DialogContent
                sx={{
                  fontFamily: "Regular",
                }}
              >
                <DialogContentText
                  id="alert-dialog-description"
                  sx={
                    {
                      // fontFamily: "Regular"
                    }
                  }
                >
                  वर्ण का क्रम सही नहीं है। कृपया शब्द के स्वर के अनुसार वर्ण का
                  क्रम लगाए।
                  <br />
                  <br />
                  संकेत:-{" "}
                  <span dangerouslySetInnerHTML={{ __html: currentFeedback }} />
                </DialogContentText>
              </DialogContent>
              <DialogActions>
                <Button
                  variant="contained"
                  onClick={handleClose1}
                  sx={
                    {
                      // fontFamily:"Regular"
                    }
                  }
                  autoFocus
                >
                  ठीक है
                </Button>
              </DialogActions>
            </Dialog>
          </div>
          <div className="d-flex justify-content-center align-items-center img-fluid">
            <NavigationNextButtons onNext={next} />
          </div>
        </div>

        // **********************************
      )}

      {/* <BackNextBar
        // setForward={onNext}
        // clickSubmit={submitoperation}
        backvisible="visible"
        nextvisible="visible"
        submitvisible="hidden"
      /> */}
    </div>
  );
}

export default LevelfirstMidContent;
