import React from "react";
import { Route, Routes, useParams } from "react-router-dom";
import Errorpage from "./components/Errorpage";
import { useTranslation } from "react-i18next";
import { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { changeLang } from "./store/Store";
import Language from "./Language";
import "../src/App.css";
import { LL5_Launchpage } from "./components/LL5_Launchpage";
import LL5_firstlevel1 from "./components/LL5_firstlevel1";
import LL5_Theory from "./components/LL5_Theory";
import LL5_Levelstart from "./components/LL5_Levelstart";
import ReactGA from "react-ga4";
import LL5_secondlevel from "./components/LL5_secondlevel";
import useWebSocket from "react-use-websocket";
import logconfig from "./config/dbconfig.js";
import { browserName, browserVersion } from "react-device-detect";
import { v4 as uuid } from "uuid";
import axios from "axios";
import LL5_secondlevel1 from "./components/LL5_secondlevel1";
import LL5_Procedure from "./components/LL5_Procedure.js";
import {L_QuizComponent} from "./quiz/L_QuizComponent.js";
import L_HelpComponent from "./Help/L_HelpComponent.js";
import "./App.css";
import LL5_secondlevel2 from "./components/LL5_secondlevel2.js";

const App = () => {
  const { t, i18n } = useTranslation();
  const { id } = useParams();
  let dispatch = useDispatch();
  let { firstStore } = useSelector((globalState) => globalState);

  //////////////////////////////ga4//////////////////////////////

  useEffect(() => {
    ReactGA.initialize("G-ZLKNSX7SDM", { 
      gaOptions: {
        gtag: true,
      },
    });
  }, []);

  /////////////////////////User Log//////////////////////////////
  const [ip, setIP] = useState("");
  const sid = uuid();

  useEffect(() => {
    localStorage.setItem("sessionid", sid);
  }, []);

  useEffect(() => {
    // to call get data function which return ip address
    getData();
  }, [ip]);

  //creating function to load ip address from the API
  const getData = async () => {
    try {
      //const res = await axios.get('https://api.ipify.org/?format=json')
      const res = await axios.get("http://10.212.8.133:8083/get_ip");
      //console.log(res.data);
      setIP(res.data.ip);
      localStorage.setItem("clientip", ip);
    } catch (error) {}
  };

  const { sendJsonMessage, readyState } = useWebSocket(logconfig.logurl, {
    onOpen: () => {
      console.log("WebSocket connection established.");
    },
    onError: () => {
      console.log("WebSocket connection Error");
    },
    share: true,
    filter: () => false,
    retryOnError: true,
    shouldReconnect: () => true,
  });

  /////////////////////////////////////////////////////////////

  useEffect(() => {
    //console.log("parameter id " + firstStore?.lang);

    if (id == "en") {
      alert("in app en : ", id);
      i18n.changeLanguage("en");
      dispatch(changeLang("en"));
    }
    if (id == "hi") {
      alert("in app hi : ", id);
      i18n.changeLanguage("hi");
      dispatch(changeLang("hi"));
    }
  }, []);
  return (
    <Routes>
      <Route path="/" element={<LL5_Launchpage />} />
      <Route path="/lang=:id" element={<App />} />
      <Route path="/letusverify" element={<LL5_Levelstart />} />

      <Route path="/level1" element={<LL5_firstlevel1 />} />

      <Route path="/level2" element={<LL5_secondlevel />} />

      <Route path="/level2_1" element={<LL5_secondlevel1 />} />

      <Route path="/level2_2" element={<LL5_secondlevel2 />} />

      <Route path="/theory_page" element={<LL5_Theory />} />

      <Route path="/help_page" element={<L_HelpComponent />} />

      <Route path="/procedure_page" element={<LL5_Procedure />} />

      <Route
        path="/quiz"
        element={<L_QuizComponent />}
      />

      <Route path="*" element={<Errorpage />} />
    </Routes>
  );
};

export default App;
