import React, { useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import play from "../Img/play.png";
import "../styles/styles.css";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import Level1 from "../Img/Level1.png";
import Level2 from "../Img/Level2.png";
import { Card } from "react-bootstrap";
import { Button } from "@mui/material";

function LevelstartMidContent({}) {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const txt = useRef(0);
  var flag = "0"; //landscape

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Level select Page");

  const handlelevel1 = () => {
    navigate("/level1");

    ReactGA.event({
      action:
        "Hindi वर्ण विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on Level-1",
      category:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 विच्छेद बनाए selected",
      label:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-1 (विच्छेद बनाए) selected",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Level-1 button",
      "Clicked",
      "level-1 विच्छेद बनाए selected"
    );
  };

  const handlelevel2 = () => {
    navigate("/level2");
    ReactGA.event({
      action:
        "Hindi वर्ण विच्छेद | CDAC-OlabsNxtG-Hindi-Lab-05 | Clicked on Level-2",
      category:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-2 शब्दों से मेल करें selected",
      label:
        "Hindi CDAC-OlabsNxtG-Hindi-Lab-05 | level-2 (शब्दों से मेल करें) selected",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Level-2 button",
      "Clicked",
      "level-2 शब्दों से मेल करें selected"
    );
  };

  return (
    <div
      className="row d-flex justify-content-center align-items-center"
      style={{
        height: "100%",
        width: "100%",
        // backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        marginLeft: "auto",
        marginRight: "auto",
        overflow: "auto",
      }}
    >
      <div className="row scrollbar-primary">
        <div className="col animate__animated animate__bounceInUp d-flex justify-content-center align-items-center mb-3">
          <Card style={{ width: "18rem" }}>
            <Card.Img variant="top" src={Level1} />
            <Card.Body className="text-center">
              <Card.Title>विच्छेद बनाएँ</Card.Title>
              <Button variant="contained" onClick={handlelevel1} 
              // sx={{fontFamily:"Regular"}}
              >
                {t("start")}
              </Button>
            </Card.Body>
          </Card>
        </div>
        <div className="col animate__animated animate__bounceInRight d-flex justify-content-center align-items-center mb-3">
          <Card style={{ width: "18rem" }}>
            <Card.Img variant="top" src={Level2} />
            <Card.Body className="text-center">
              <Card.Title>वर्ण-विच्छेद और शब्द का मेल</Card.Title>
              <Button variant="contained" onClick={handlelevel2} 
              // sx={{fontFamily:"Regular"}}
              >
                {t("start")}
              </Button>
            </Card.Body>
          </Card>
        </div>
      </div>
    </div>
  );
}

export default LevelstartMidContent;
