import { Launchpage } from "Hindi-olabsnxtg-library";
import React from "react";
import { useTranslation } from "react-i18next";
import ActStartPopupContent from "./ActStartPopupContent";
import ReactGA from "react-ga4";
import { useEffect } from "react";
import logconfig from '../config/dbconfig.js';
import {SendLogData} from "../config/wslog.js";
import useWebSocket from 'react-use-websocket';

export const LL5_Launchpage = () => {

  useEffect(() => {
    ReactGA.send({ hitType: "pageview", page: "Hi5/", title: "Hi5 | वर्ण-विच्छेद launchpage" });
   }, []);

  const { t, i18n } = useTranslation();
  var arr = [t("learning_out_title1"), t("learning_out_title2"),<><strong>{t("prerequisite")}</strong> {t("prerequisite_1")}</>];
  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});

  return (
    <Launchpage
      L_title={t("title")}
      L_objective={t("Objective")}
      L_act_objective={t("objectivedef")}
      L_array={arr}
      L_learning_outcome={t("learning_out_title")}
      L_startbutton={t("start")}
      L_actstartPopup_content_comp={<ActStartPopupContent />}
      L_actstartPopup_content_title={t("what_we_are_going_to_learn_title")}
      L_ok={t("yes")}
      L_cancel={t("cancel")}

      WS_sendJsonMessage={sendJsonMessage}
      WS_sendLogData={SendLogData}
      L_labName="वर्ण विच्छेद"
      L_labUniqueName="CDAC-OlabsNxtG-Hindi-Lab-05"
    />
  );
};
