import React, { useEffect } from 'react'
import hindi_bg from "../Img/hindi_bg.jpg"
import * as Instru from "./Instruction.js";
import {Headcomp} from 'Hindi-olabsnxtg-library'
import {Footercomp} from 'Hindi-olabsnxtg-library'
import {Middlecomp} from 'Hindi-olabsnxtg-library'
import { useState } from "react";
import { ToastContainer, toast } from "react-toastify"; 
import { useTranslation } from "react-i18next";
import Levelsecond1MidContent from './Levelsecond1MidContent';
import logconfig from '../config/dbconfig.js';
import {SendLogData} from "../config/wslog.js";
import useWebSocket from 'react-use-websocket';
import ReactGA from "react-ga4";
import QuizPopupContent from '../quiz/QuizPopupContent.js';

const LL5_secondlevel1 = () => {
    const { t, i18n } = useTranslation();

    let details = navigator.userAgent;
    let regexp = /android|iphone|kindle|ipad/i;
    let isMobileDevice = regexp.test(details);
  
    const [instruct, setInstruct] = useState("")
    const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});
  
    useEffect(() => {
      if (isMobileDevice) {
        console.log("in mobile device");
        setInstruct(Instru.Instruction_5(t));
      } else {
        setInstruct(Instru.Instruction_3(t));
      }
    }, [])
  
    ReactGA.send({
      hitType: "pageview",
      page: "L05/level2_1",
      title: "L05 | वर्ण-विच्छेद",
    });
  return (
    <div
     style={{
        height: "100vh",
        backgroundImage: "url(" + hindi_bg + ")",
        backgroundSize: "100% 100%",
        backgroundRepeat: "no-repeat",
        maxHeight: "100%",
      }}
    >
      <Headcomp
        H_title={t("title")}
        H_sidebarvisible="visible"
        HQ_quittext={t("want_to_quit")}
        HQ_yes={t("yes")}
        HQ_cancel={t("cancel")}
        RSM_QuizPopupContent_comp={<QuizPopupContent/>}
        RSM_Intruc_popup_title_string={t("quiz_instruction")}
        RSM_ok={t("yes")}
        RSM_theory_tt={t("theory")}
        RSM_vivavoce_tt={t("viva_voce")}
        RSM_procedure_tt={t("procedure")}
        RSM_help_tt={t("help")} 
        RSM_menu_tt={t("menu")}
        RSM_theoryvisible="visible"
        RSM_procedurevisible="visible"
        RSM_vivavocevisible="visible"
        RSM_helpvisible="visible"
        WS_sendJsonMessage={sendJsonMessage}
        WS_sendLogData={SendLogData}
        L_labName="वर्ण-विच्छेद"
        L_labUniqueName="CDAC-OlabsNxtG-Hindi-Lab-05"
      />
      
      <Footercomp  
        F_footheight="15%" 
        F_instruction={instruct}
        F_instructionlabel={t("instruction")}
      />

      <br/>

      <Middlecomp 
         M_midheight="70%"
         M_midcontent={<Levelsecond1MidContent changeInst={(e)=>{setInstruct(e)}}/>}
      />

      <ToastContainer />
    </div>
  )
}

export default LL5_secondlevel1