import React from "react";
import { ListItemText } from "@mui/material";
import { useTranslation } from "react-i18next";
import "../App.css";

const ActStartPopupContent = () => {
  const { t, i18n } = useTranslation();
  return (
    <ul >
      <li>{t("what_going_to_learn_1")}</li>
      <li>
        {t("what_going_to_learn_2")}
        <br />
        {t("what_going_to_learn_3")}
        <br />
        {t("what_going_to_learn_4")}
      </li>
      <li>{t("what_going_to_learn_5")}</li>
      <li>{t("what_going_to_learn_6")}</li>
    </ul>
  );
};

export default ActStartPopupContent;
