import React from "react";

function TableStructure({ table }) {
  const { columns, rows } = table;

  console.log("{column, rows} ", { columns, rows });
  return (
    <div style={{overflowX:"auto"}}>
      <table border="1" cellPadding="10" cellSpacing="0" >
        <thead>
          <tr>
            <th style={{border:"1px solid black"}}></th> 
            {columns.map((col, index) => (
              <th key={index} style={{border:"1px solid black", backgroundColor:"rgb(231, 225, 255)"}}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => (
            <tr key={rowIndex} style={{border:"1px solid black"}}>
              <td style={{border:"1px solid black", backgroundColor:"rgb(231, 225, 255)"}}>
                <strong>{row.type}</strong>
              </td>
              {row.data.map((cell, colIndex) => (
                <td key={colIndex} style={{border:"1px solid black", textAlign:"center"}}>{cell}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default TableStructure;